import { RouterProvider } from 'react-router-dom'
import { useEffect } from 'react'
import { router } from '@/router'
import { useAuthStore } from '@/store/authStore'
import { apiClient } from '@/api/client'

export default function App() {
  useEffect(() => {
    const initializeAuth = async () => {
      const user = useAuthStore.getState().user
      const token = useAuthStore.getState().accessToken

      // Si hay usuario pero no hay token, intentar refrescar
      if (user && !token) {
        try {
          const { data } = await apiClient.post('/auth/refresh', {})
          useAuthStore.getState().setAccessToken(data.accessToken)
        } catch (error) {
          // Si no se puede refrescar, limpiar la autenticación
          useAuthStore.getState().clearAuth()
        }
      }
    }

    initializeAuth()
  }, [])

  return <RouterProvider router={router} />
}

import axios from 'axios'
import { useAuthStore } from '@/store/authStore'

// En desarrollo, usa el proxy de Vite (/api). En producción, usa la URL completa.
const API_BASE_URL = import.meta.env.DEV ? '/api' : (import.meta.env.VITE_API_URL || 'http://localhost:4000/api')

export const apiClient = axios.create({
  baseURL: API_BASE_URL,
  withCredentials: true, // envía cookies httpOnly (refresh token)
})

// Attach access token to every request
apiClient.interceptors.request.use((config) => {
  const token = useAuthStore.getState().accessToken
  if (token) {
    config.headers.Authorization = `Bearer ${token}`
  }
  return config
})

// Auto-refresh on 401
let isRefreshing = false
let refreshQueue: Array<(token: string) => void> = []

apiClient.interceptors.response.use(
  (response) => response,
  async (error) => {
    const original = error.config

    if (error.response?.status === 401 && !original._retry) {
      original._retry = true

      if (isRefreshing) {
        return new Promise((resolve) => {
          refreshQueue.push((token) => {
            original.headers.Authorization = `Bearer ${token}`
            resolve(apiClient(original))
          })
        })
      }

      isRefreshing = true

      try {
        const refreshUrl = import.meta.env.DEV ? '/api/auth/refresh' : `${API_BASE_URL}/auth/refresh`
        const { data } = await axios.post(refreshUrl, {}, { withCredentials: true })
        const newToken: string = data.accessToken

        useAuthStore.getState().setAccessToken(newToken)
        refreshQueue.forEach((cb) => cb(newToken))
        refreshQueue = []

        original.headers.Authorization = `Bearer ${newToken}`
        return apiClient(original)
      } catch {
        useAuthStore.getState().clearAuth()
        window.location.href = '/login'
        return Promise.reject(error)
      } finally {
        isRefreshing = false
      }
    }

    return Promise.reject(error)
  },
)

import { describe, it, expect, vi, beforeEach } from 'vitest'

// Declarar variables en el scope global (antes de vi.mock)
let mockGet: any
let mockPatch: any
let mockPost: any

// Mock de apiClient
vi.mock('@/api/client', () => ({
  apiClient: {
    get: vi.fn((url: string) => mockGet(url)),
    patch: vi.fn((url: string, data: any) => mockPatch(url, data)),
    post: vi.fn((url: string, data: any) => mockPost(url, data)),
  },
}))

import { usersApi } from './users.api'

describe('UsersAPI', () => {
  beforeEach(() => {
    mockGet = vi.fn()
    mockPatch = vi.fn()
    mockPost = vi.fn()
  })

  describe('getMe', () => {
    it('fetches current user profile', async () => {
      const mockUser = {
        id: 'user-1',
        email: 'test@uta.edu.ec',
        fullName: 'Test User',
        career: 'CS',
        phone: null,
        photoUrl: null,
        neighborhood: null,
        role: 'STUDENT' as const,
        status: 'ACTIVE',
        reputationScore: 5.0,
        totalTrips: 0,
        emailVerified: true,
        createdAt: '2024-01-01T00:00:00Z',
        vehicle: null,
      }

      mockGet.mockResolvedValue({ data: { user: mockUser } })

      const result = await usersApi.getMe()

      expect(result.data.user).toEqual(mockUser)
      expect(mockGet).toHaveBeenCalledWith('/users/me')
    })

    it('throws error when request fails', async () => {
      mockGet.mockRejectedValue(new Error('Network error'))

      await expect(usersApi.getMe()).rejects.toThrow('Network error')
    })
  })

  describe('updateMe', () => {
    it('updates user profile with partial data', async () => {
      const updateData = { fullName: 'New Name', phone: '1234567890' }
      const updatedUser = { id: 'user-1', ...updateData }

      mockPatch.mockResolvedValue({ data: { user: updatedUser } })

      const result = await usersApi.updateMe(updateData)

      expect(mockPatch).toHaveBeenCalledWith('/users/me', updateData)
      expect(result.data.user.fullName).toBe('New Name')
    })

    it('accepts empty update object', async () => {
      mockPatch.mockResolvedValue({ data: { user: {} } })

      await usersApi.updateMe({})

      expect(mockPatch).toHaveBeenCalledWith('/users/me', {})
    })
  })

  describe('createVehicle', () => {
    it('creates a new vehicle', async () => {
      const vehicleData = {
        brand: 'Toyota',
        model: 'Corolla',
        year: 2020,
        plateNumber: 'ABC1234',
        color: 'Blanco',
      }
      const createdVehicle = { id: 'veh-1', ...vehicleData }

      mockPost.mockResolvedValue({ data: { vehicle: createdVehicle } })

      const result = await usersApi.createVehicle(vehicleData)

      expect(mockPost).toHaveBeenCalledWith('/users/me/vehicle', vehicleData)
      expect(result.data.vehicle).toEqual(createdVehicle)
    })

    it('throws error when vehicle already exists', async () => {
      const vehicleData = {
        brand: 'Toyota',
        model: 'Corolla',
        year: 2020,
        plateNumber: 'ABC1234',
        color: 'Blanco',
      }

      mockPost.mockRejectedValue({
        response: {
          status: 409,
          data: { error: 'Ya tienes un vehículo registrado' },
        },
      })

      await expect(usersApi.createVehicle(vehicleData)).rejects.toMatchObject({
        response: { status: 409 },
      })
    })
  })

  describe('updateVehicle', () => {
    it('updates existing vehicle', async () => {
      const updateData = { color: 'Negro', year: 2021 }
      const updatedVehicle = { id: 'veh-1', ...updateData }

      mockPatch.mockResolvedValue({ data: { vehicle: updatedVehicle } })

      const result = await usersApi.updateVehicle(updateData)

      expect(mockPatch).toHaveBeenCalledWith('/users/me/vehicle', updateData)
      expect(result.data.vehicle.color).toBe('Negro')
    })

    it('throws error when vehicle does not exist', async () => {
      mockPatch.mockRejectedValue({
        response: {
          status: 404,
          data: { error: 'No tienes vehículo registrado' },
        },
      })

      await expect(usersApi.updateVehicle({ color: 'Rojo' })).rejects.toMatchObject({
        response: { status: 404 },
      })
    })
  })
})

import { useState, useEffect, useRef, useMemo } from 'react'
import { MapContainer, TileLayer, Marker, Popup, useMap } from 'react-leaflet'
import L from 'leaflet'
import 'leaflet/dist/leaflet.css'

// Fix Leaflet default icon paths broken by Vite's asset hashing
delete (L.Icon.Default.prototype as unknown as Record<string, unknown>)._getIconUrl
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
  iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
  shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
})

const destIcon = L.divIcon({
  className: '',
  html: `
    <div style="position:relative;width:32px;height:32px;display:flex;align-items:center;justify-content:center;">
      <div style="position:absolute;width:32px;height:32px;background:rgba(0,252,64,0.15);border-radius:50%;"></div>
      <div style="width:14px;height:14px;background:#00fc40;border-radius:50%;border:2px solid #fff;box-shadow:0 0 8px rgba(0,252,64,0.6);"></div>
    </div>
  `,
  iconSize: [32, 32],
  iconAnchor: [16, 16],
})

const originIcon = L.divIcon({
  className: '',
  html: `
    <div style="position:relative;width:32px;height:32px;display:flex;align-items:center;justify-content:center;">
      <div style="position:absolute;width:32px;height:32px;background:rgba(0,122,255,0.15);border-radius:50%;"></div>
      <div style="width:14px;height:14px;background:#007aff;border-radius:50%;border:2px solid #fff;box-shadow:0 0 8px rgba(0,122,255,0.6);"></div>
    </div>
  `,
  iconSize: [32, 32],
  iconAnchor: [16, 16],
})

const CAMPUS_COORDS: Record<string, [number, number]> = {
  'Campus Central UTA — Huachi': [-1.2491, -78.6167],
  'Facultad de Ingeniería Civil (FICE)': [-1.2505, -78.6182],
  'Facultad de Ingeniería en Sistemas (FISI)': [-1.2478, -78.6153],
  'Facultad de Ciencias Administrativas (FCA)': [-1.2466, -78.6171],
  'Facultad de Ciencias Humanas y de la Educación (FCHE)': [-1.2512, -78.6148],
  'Facultad de Diseño, Arquitectura y Artes (FDAA)': [-1.2498, -78.6138],
  'Facultad de Ciencias de la Salud (FCS)': [-1.2483, -78.6194],
  'Facultad de Jurisprudencia (FJ)': [-1.2471, -78.6208],
}
const UTA_CENTER: [number, number] = [-1.2491, -78.6167]

interface RouteMapProps {
  originZone: string
  destinationZone: string
  interactive?: boolean
  onOriginSelect?: (address: string) => void
  onDestinationSelect?: (address: string) => void
}

async function getStreetAddress(lat: number, lng: number): Promise<string> {
  try {
    const res = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json`)
    const data = await res.json()
    if (data && data.address) {
      const road = data.address.road || ''
      const secondary = data.address.neighbourhood || data.address.suburb || data.address.residential || data.address.hamlet || ''
      const city = data.address.city || data.address.town || data.address.village || ''
      
      let addr = ''
      if (road && secondary && road !== secondary) {
        addr = `${road} y ${secondary}`
      } else if (road) {
        addr = road
      } else if (secondary) {
        addr = secondary
      } else {
        addr = 'Ubicación seleccionada'
      }
      return city ? `${addr}, ${city}` : addr
    }
  } catch (err) {
    console.error("Geocoding failed", err)
  }
  return 'Ubicación seleccionada'
}

function DraggableMarker({
  position,
  icon,
  label,
  subLabel,
  interactive,
  onLocationChange,
}: {
  position: [number, number] | null
  icon: L.DivIcon
  label: string
  subLabel: string
  interactive: boolean
  onLocationChange?: (addr: string) => void
}) {
  const markerRef = useRef<L.Marker>(null)

  const eventHandlers = useMemo(
    () => ({
      dragend() {
        const marker = markerRef.current
        if (marker != null) {
          const pos = marker.getLatLng()
          if (onLocationChange) {
            getStreetAddress(pos.lat, pos.lng).then(onLocationChange)
          }
        }
      },
    }),
    [onLocationChange],
  )

  if (!position) return null

  return (
    <Marker
      draggable={interactive}
      eventHandlers={eventHandlers}
      position={position}
      ref={markerRef}
      icon={icon}
      autoPan={true}
    >
      <Popup className="leaflet-popup-dark" minWidth={100}>
        <span style={{ fontSize: '11px', fontWeight: 'bold', display: 'block' }}>{label}</span>
        <span style={{ fontSize: '11px', color: '#a0a0a0' }}>{subLabel || 'Aún no seleccionado'}</span>
        {interactive && (
          <span style={{ fontSize: '9px', color: '#8af2ff', display: 'block', marginTop: '4px', fontStyle: 'italic' }}>
            (Arrastra el marcador para ajustarlo)
          </span>
        )}
      </Popup>
    </Marker>
  )
}

function MapController({ interactive, onLocated }: { interactive: boolean, onLocated: (pos: [number, number]) => void }) {
  const map = useMap()
  const [located, setLocated] = useState(false)
  useEffect(() => {
    if (!interactive || located) return
    map.locate({ enableHighAccuracy: true }).on("locationfound", function (e) {
      if (located) return
      setLocated(true)
      const pos: [number, number] = [e.latlng.lat, e.latlng.lng]
      onLocated(pos)
      map.flyTo(e.latlng, 15)
    })
  }, [map, interactive, located, onLocated])
  return null
}

export default function RouteMap({ originZone, destinationZone, interactive = false, onOriginSelect, onDestinationSelect }: RouteMapProps) {
  const [originCoords, setOriginCoords] = useState<[number, number] | null>(null)
  const [destCoords, setDestCoords] = useState<[number, number] | null>(null)

  useEffect(() => {
    if (interactive) return

    let isMounted = true

    if (originZone) {
      fetch(`https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(originZone + ', Ambato, Ecuador')}&format=json&limit=1`)
        .then(r => r.json())
        .then(d => { if (isMounted && d && d[0]) setOriginCoords([parseFloat(d[0].lat), parseFloat(d[0].lon)]) })
    }
    if (destinationZone) {
      if (CAMPUS_COORDS[destinationZone]) {
        setDestCoords(CAMPUS_COORDS[destinationZone])
      } else {
        fetch(`https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(destinationZone + ', Ambato, Ecuador')}&format=json&limit=1`)
          .then(r => r.json())
          .then(d => { if (isMounted && d && d[0]) setDestCoords([parseFloat(d[0].lat), parseFloat(d[0].lon)]) })
      }
    }
    
    return () => { isMounted = false }
  }, [interactive, originZone, destinationZone])

  const handleLocated = (pos: [number, number]) => {
    setOriginCoords(pos)
    const dPos: [number, number] = [pos[0] + 0.003, pos[1] + 0.003]
    setDestCoords(dPos)
    if (onOriginSelect && !originZone) getStreetAddress(pos[0], pos[1]).then(onOriginSelect)
    if (onDestinationSelect && !destinationZone) getStreetAddress(dPos[0], dPos[1]).then(onDestinationSelect)
  }

  const displayOrigin = interactive ? (originCoords || UTA_CENTER) : originCoords
  const displayDest = interactive ? (destCoords || [UTA_CENTER[0] + 0.003, UTA_CENTER[1] + 0.003]) : destCoords
  const center = displayOrigin || displayDest || UTA_CENTER

  return (
    <MapContainer
      center={center}
      zoom={14}
      style={{ width: '100%', height: '100%' }}
      zoomControl={interactive}
      attributionControl={false}
      scrollWheelZoom={interactive}
      dragging={interactive}
      doubleClickZoom={interactive}
    >
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        className="map-tiles-dark"
      />
      <MapController interactive={interactive} onLocated={handleLocated} />

      <DraggableMarker
        position={displayOrigin}
        icon={originIcon}
        label="Punto de Partida"
        subLabel={originZone}
        interactive={interactive}
        onLocationChange={onOriginSelect}
      />

      <DraggableMarker
        position={displayDest}
        icon={destIcon}
        label="Punto de Llegada"
        subLabel={destinationZone}
        interactive={interactive}
        onLocationChange={onDestinationSelect}
      />
    </MapContainer>
  )
}

import { useState } from 'react'
import { useMutation, useQueryClient } from '@tanstack/react-query'
import { ratingsApi } from '@/api/ratings.api'

interface RatingModalProps {
  tripRequestId: string
  driverName: string
  onClose: () => void
}

export default function RatingModal({ tripRequestId, driverName, onClose }: RatingModalProps) {
  const [score, setScore] = useState(0)
  const [hovered, setHovered] = useState(0)
  const [comment, setComment] = useState('')
  const [serverError, setServerError] = useState('')
  const qc = useQueryClient()

  const mutation = useMutation({
    mutationFn: () => ratingsApi.createRating({ tripRequestId, score, comment: comment || undefined }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['my-requests'] })
      onClose()
    },
    onError: (err: unknown) => {
      const msg =
        (err as { response?: { data?: { message?: string } } })?.response?.data?.message ??
        'Error al enviar la calificación'
      setServerError(msg)
    },
  })

  const displayScore = hovered || score

  return (
    /* Backdrop */
    <div
      className="fixed inset-0 z-50 flex items-center justify-center px-4 bg-black/70 backdrop-blur-sm"
      onClick={(e) => { if (e.target === e.currentTarget) onClose() }}
    >
      <div className="w-full max-w-sm bg-surface-container-low rounded-2xl shadow-2xl overflow-hidden">

        {/* Header */}
        <div className="p-6 border-b border-white/5">
          <div className="flex items-center justify-between mb-1">
            <h2 className="font-headline text-xl font-bold text-white">Calificar Conductor</h2>
            <button
              onClick={onClose}
              className="text-on-surface-variant hover:text-white transition-colors"
            >
              <span className="material-symbols-outlined">close</span>
            </button>
          </div>
          <p className="text-on-surface-variant text-sm">{driverName}</p>
        </div>

        <div className="p-6 space-y-6">
          {/* Stars */}
          <div className="flex flex-col items-center gap-3">
            <p className="text-on-surface-variant text-xs uppercase tracking-widest font-bold">
              {displayScore === 0
                ? 'Selecciona una puntuación'
                : displayScore === 1 ? 'Muy malo'
                : displayScore === 2 ? 'Regular'
                : displayScore === 3 ? 'Bueno'
                : displayScore === 4 ? 'Muy bueno'
                : 'Excelente'}
            </p>
            <div className="flex gap-2">
              {[1, 2, 3, 4, 5].map((star) => (
                <button
                  key={star}
                  type="button"
                  onClick={() => setScore(star)}
                  onMouseEnter={() => setHovered(star)}
                  onMouseLeave={() => setHovered(0)}
                  className="transition-transform hover:scale-110 active:scale-95"
                >
                  <span
                    className={`material-symbols-outlined text-4xl transition-colors ${
                      star <= displayScore
                        ? 'text-primary material-symbols-filled'
                        : 'text-outline'
                    }`}
                  >
                    star
                  </span>
                </button>
              ))}
            </div>
          </div>

          {/* Comment */}
          <div>
            <label className="block text-[10px] font-bold text-on-surface-variant uppercase tracking-widest mb-2">
              Comentario <span className="normal-case text-zinc-600">(opcional)</span>
            </label>
            <textarea
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              rows={3}
              maxLength={300}
              placeholder="¿Cómo fue tu experiencia con este conductor?"
              className="w-full bg-surface-container-highest border-none rounded-xl p-4 text-on-surface placeholder:text-outline text-sm resize-none focus:ring-1 focus:ring-primary/40 outline-none"
            />
          </div>

          {serverError && (
            <div className="flex items-center gap-2 bg-error/10 border border-error/20 rounded-lg px-3 py-2">
              <span className="material-symbols-outlined text-error text-sm">error</span>
              <p className="text-sm text-error">{serverError}</p>
            </div>
          )}

          {/* Actions */}
          <div className="space-y-3">
            <button
              onClick={() => mutation.mutate()}
              disabled={score === 0 || mutation.isPending}
              className="w-full bg-gradient-primary py-3 rounded-xl text-on-primary font-headline font-bold uppercase tracking-wider transition-all hover:shadow-[0_0_20px_rgba(156,255,147,0.3)] disabled:opacity-40 disabled:cursor-not-allowed active:scale-[0.98]"
            >
              {mutation.isPending ? 'Enviando...' : 'Enviar Calificación'}
            </button>
            <button
              onClick={onClose}
              className="w-full py-2 text-on-surface-variant hover:text-white text-sm font-medium transition-colors"
            >
              Cancelar
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { useMutation } from '@tanstack/react-query'
import { useNavigate, Link } from 'react-router-dom'
import { authApi } from '@/api/auth.api'

const forgotPasswordSchema = z.object({
  email: z.string().email('Correo inválido'),
})

type ForgotPasswordForm = z.infer<typeof forgotPasswordSchema>

export default function ForgotPassword() {
  const navigate = useNavigate()
  const [success, setSuccess] = useState(false)

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<ForgotPasswordForm>({
    resolver: zodResolver(forgotPasswordSchema),
  })

  const forgotMutation = useMutation({
    mutationFn: (data: ForgotPasswordForm) => authApi.forgotPassword(data),
    onSuccess: () => {
      setSuccess(true)
      setTimeout(() => navigate('/reset-password'), 2000)
    },
  })

  return (
    <div className="min-h-screen bg-surface text-on-surface font-body flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        {/* Background blobs */}
        <div className="absolute -top-24 -right-24 w-96 h-96 bg-primary/10 rounded-full blur-[120px]" />
        <div className="absolute top-1/2 -left-24 w-64 h-64 bg-tertiary/5 rounded-full blur-[80px]" />

        <div className="bg-surface-container p-8 md:p-12 rounded-2xl border border-outline-variant/5 relative z-10">
          <h2 className="text-3xl font-headline font-bold mb-2 text-on-surface">Recupera tu contraseña</h2>
          <p className="text-on-surface-variant mb-8">Ingresa tu correo institucional y recibirás un código para recuperar tu contraseña</p>

          {success && (
            <div className="mb-6 flex items-center gap-3 bg-primary/10 border border-primary/20 rounded-lg px-4 py-3">
              <span className="text-sm text-primary font-medium">
                ✓ Correo enviado correctamente. Redirigiendo...
              </span>
            </div>
          )}

          {forgotMutation.isError && (
            <div className="mb-6 flex items-center gap-3 bg-error/10 border border-error/20 rounded-lg px-4 py-3">
              <span className="text-sm text-error font-medium">
                ✕ {(forgotMutation.error as any)?.response?.data?.error || 'Error al enviar el código'}
              </span>
            </div>
          )}

          <form onSubmit={handleSubmit((data) => forgotMutation.mutate(data))} className="space-y-6">
            <div>
              <label className="block text-xs font-label uppercase tracking-widest text-on-surface-variant mb-2">
                Correo Institucional
              </label>
              <input
                {...register('email')}
                type="email"
                placeholder="usuario@uta.edu.ec"
                className="w-full bg-surface-container-highest border-none rounded-lg p-4 focus:ring-1 focus:ring-primary/40 focus:bg-surface-bright transition-all outline-none text-on-surface placeholder:text-outline"
                disabled={isSubmitting}
              />
              {errors.email && (
                <p className="mt-1 text-xs text-error">{errors.email.message}</p>
              )}
            </div>

            <button
              type="submit"
              disabled={isSubmitting || forgotMutation.isPending}
              className="w-full bg-primary text-on-primary font-semibold py-3 rounded-lg transition hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed font-headline tracking-tight"
            >
              {isSubmitting || forgotMutation.isPending ? 'Enviando...' : 'Enviar código'}
            </button>
          </form>

          <div className="mt-6 text-center border-t border-outline-variant/10 pt-6">
            <p className="text-on-surface-variant text-sm mb-4">
              ¿Ya tienes el código?{' '}
